#!/usr/bin/env python3
import json
import os
import sys


def main():
    if len(sys.argv) != 2:
        print("usage: probe.py <directory>", file=sys.stderr)
        return 1

    directory = sys.argv[1]
    output_path = "summary.json"

    if os.path.exists(output_path):
        print(f"error: {output_path} already exists, refusing to overwrite", file=sys.stderr)
        return 1

    try:
        entries = os.listdir(directory)
    except OSError as e:
        print(f"error: cannot read directory {directory}: {e}", file=sys.stderr)
        return 1

    values = []
    for name in entries:
        if not name.endswith(".json"):
            continue
        path = os.path.join(directory, name)
        if not os.path.isfile(path):
            continue
        try:
            with open(path, "r") as f:
                data = json.load(f)
        except (OSError, json.JSONDecodeError):
            continue
        if isinstance(data, dict) and "cost_usd" in data:
            values.append(data["cost_usd"])

    total = sum(values)
    mean = total / len(values) if values else 0

    summary = {"total": total, "mean": mean}

    try:
        with open(output_path, "x") as f:
            json.dump(summary, f)
    except FileExistsError:
        print(f"error: {output_path} already exists, refusing to overwrite", file=sys.stderr)
        return 1

    return 0


if __name__ == "__main__":
    sys.exit(main())
